import * as React from "react"
import { formatDate, lineTotal, money, totals } from "../../../lib/invoice"

/**
 * What every invoice template is handed.
 * ============================================================================
 * Eight designs, one set of numbers. Each template decides how an invoice
 * LOOKS — bands, rules, sidebars, stubs — and none of them decides what it
 * SAYS or what it adds up to. That lives in lib/invoice.js and arrives here
 * already computed, so a design cannot quietly disagree with its own totals.
 *
 * ── EMPTY FIELDS STAY EMPTY ────────────────────────────────────────────────
 * Nothing here substitutes "Your Company Name" for a blank. A placeholder that
 * survives into a PDF sent to a customer is worse than a gap, because a gap is
 * obviously unfinished and a grey "Client Name" looks deliberate.
 */
export function prepare(invoice) {
  const sums = totals(invoice)
  const currency = invoice.currency

  // A row that is entirely untouched is not a line item; it is an empty form
  // field the contractor has not got to yet.
  const lines = invoice.lines
    .filter(line => line.description.trim() || Number(line.quantity) || Number(line.rate))
    .map(line => ({
      ...line,
      // The first line of a description doubles as its title in the designs
      // that have a separate "Service"/"Description" pair.
      title: line.description.split("\n")[0].trim(),
      rest: line.description.split("\n").slice(1).join("\n").trim(),
      period: (line.period || "").trim(),
      amount: lineTotal(line),
    }))

  const fmt = value => money(value, currency)

  return {
    sums,
    currency,
    lines,
    fmt,
    issued: formatDate(invoice.issuedOn),
    due: formatDate(invoice.dueOn),
    taxLabel: invoice.taxLabel || "Tax",
    taxRate: Number(invoice.taxRate) || 0,
    discountPct: invoice.discountMode === "percent" ? Number(invoice.discountValue) || 0 : 0,
    hasDiscount: sums.discount > 0,
    hasTax: (Number(invoice.taxRate) || 0) > 0,
    hasPaid: sums.paid > 0,
  }
}

/** Address blocks are multi-line free text; this keeps the breaks. */
export const lines2 = value => String(value || "").trim()

