/**
 * INVOICE LAYOUTS — the shape of the page, separate from its colour.
 * ============================================================================
 * The standard layout is the one Nate specified and is the default. The others
 * are genuinely different structures — a coloured rail, a perforated stub, a
 * pair of sweeping curves — not recolours, because a recolour is what the
 * palette list is for.
 *
 * Adding a layout is a row here plus a component in the registry in
 * components/invoice/InvoiceDoc.js. Every layout reads the SAME palette, so a
 * new one costs nothing in colour work.
 */

export const INVOICE_LAYOUTS = [
  {
    id: "agency",
    label: "Standard",
    blurb: "Dark bands top and bottom, overhanging logo block, filled total bar.",
  },
  {
    id: "detailed",
    label: "Detailed",
    blurb: "Split header with the numbers inside it, a job-details grid and a payments table.",
  },
  {
    id: "panel",
    label: "Panel",
    blurb: "Accent block at the corner, contacts in the header, numbered rows.",
  },
  {
    id: "signature",
    label: "Signature",
    blurb: "Curved header, an accent reference strip, a payment box and a signed foot.",
  },
  {
    id: "arc",
    label: "Arc",
    blurb: "Sweeping curves top and bottom, a tinted stats grid and a period column.",
  },
  {
    id: "bright",
    label: "Bright",
    blurb: "Light header with a rounded accent tab. Contacts up top, no dark bands.",
  },
  {
    id: "sidebar",
    label: "Sidebar",
    blurb: "Your details run down a full-height coloured rail.",
  },
  {
    id: "ticket",
    label: "Ticket",
    blurb: "Perforated stub carrying the reference, date and amount.",
  },
]

export const DEFAULT_LAYOUT = INVOICE_LAYOUTS[0]

/**
 * Falls back to the default rather than throwing, which is what makes removing
 * a layout safe: a draft saved against one that no longer exists opens in
 * Standard instead of a blank page.
 */
export function layoutById(id) {
  return INVOICE_LAYOUTS.find(l => l.id === id) || DEFAULT_LAYOUT
}
