import * as React from "react"
import { formatDate, money } from "../../../lib/invoice"
import { prepare, MailIcon, PhoneIcon, PinIcon } from "./shared"
import * as s from "./Arc.module.css"

/**
 * ARC — sweeping curves top and bottom, a tinted stats grid, a payment summary.
 *
 * What makes it the fifth distinct shape rather than another rectangle:
 *
 *  1. Two ORGANIC shapes bracket the page — an accent swoosh cutting across
 *     the dark header, and a dark wedge answering it at the bottom-right. Every
 *     other design here is built from straight edges.
 *  2. The word INVOICE sits at the top-LEFT inside the header, in the accent,
 *     with the reference line directly beneath it rather than off to one side.
 *  3. The stats grid is three-across in two rows, with the cells separated by
 *     gaps in a tinted field rather than by borders. Same optional data as
 *     Detailed and Panel; a third way of reading it.
 *  4. The footer is contact rows on WHITE with icons, not a dark band.
 *
 * The items table gains a Period column, which is the point of this layout:
 * recurring or date-bounded work, where "what and when" matters as much as
 * "how much".
 */

/* The curves are inline SVG rather than border-radius: a border-radius can
   only round a corner, and these cut across the whole band. Drawn on the
   element's own viewBox with preserveAspectRatio="none" so they stretch
   exactly to the header and footer, whatever the paper. */

const TopCurve = ({ className }) => (
  <svg className={className} viewBox="0 0 794 150" preserveAspectRatio="none" aria-hidden="true">
    <rect width="794" height="150" fill="var(--ink)" />
    <path d="M794 0 H392 Q566 62 286 150 H794 Z" fill="var(--c)" />
  </svg>
)

const BottomCurve = ({ className }) => (
  <svg className={className} viewBox="0 0 360 180" preserveAspectRatio="none" aria-hidden="true">
    <path d="M360 0 Q196 34 116 180 H360 Z" fill="var(--ink)" />
    <circle cx="288" cy="52" r="46" fill="#fff" opacity="0.07" />
  </svg>
)

const Arc = ({ invoice, t }) => {
  const v = prepare(invoice)

  const details = (invoice.details || []).filter(d => d.label.trim() || d.value.trim())
  const payment = (invoice.payments || []).find(
    p => p.method.trim() || p.reference.trim() || Number(p.amount)
  )
  const anyPeriod = v.lines.some(line => line.period)

  return (
    <div
      className={s.page}
      style={{ "--c": t.primary, "--on-c": t.onPrimary, "--a": t.accent, "--ink": t.ink, "--surface": t.surface }}
    >
      <header className={s.head}>
        <TopCurve className={s.topCurve} />
        <div className={s.headInner}>
          <p className={s.word}>Invoice</p>
          <p className={s.ref}>
            {invoice.number.trim() ? (
              <span>
                <strong>Invoice No:</strong>
                {invoice.number}
              </span>
            ) : null}
            {v.issued ? (
              <span>
                <strong>Invoice Date:</strong>
                {v.issued}
              </span>
            ) : null}
          </p>
        </div>
      </header>

      <div className={s.body}>
        <section className={s.parties}>
          <div>
            <p className={s.partyLabel}>Bill To:</p>
            {invoice.to.name.trim() ? <p className={s.partyName}>{invoice.to.name}</p> : null}
            {invoice.to.address.trim() ? <p className={s.partyLine}>{invoice.to.address}</p> : null}
            {invoice.to.email.trim() ? <p className={s.partyLine}>{invoice.to.email}</p> : null}
          </div>
          <div className={s.right}>
            {invoice.from.logo ? (
              <img src={invoice.from.logo} alt="" className={s.logo} />
            ) : invoice.from.name.trim() ? (
              <p className={s.house}>{invoice.from.name}</p>
            ) : null}
            {invoice.from.address.trim() ? (
              <p className={s.houseLine}>{invoice.from.address}</p>
            ) : null}
          </div>
        </section>

        {details.length > 0 && (
          <section className={s.stats}>
            {details.slice(0, 6).map(d => (
              <div key={d.id}>
                <span className={s.statLabel}>{d.label}:</span>
                <span className={s.statValue}>{d.value}</span>
              </div>
            ))}
          </section>
        )}

        <table className={s.table}>
          <thead>
            <tr>
              <th className={s.colNo}>Sr No</th>
              <th className={s.colDesc}>Details</th>
              {anyPeriod ? <th className={s.colPeriod}>Period</th> : null}
              <th className={s.colAmount}>Amount</th>
            </tr>
          </thead>
          <tbody>
            {v.lines.length === 0 ? (
              <tr>
                <td colSpan={anyPeriod ? 4 : 3} className={s.empty}>
                  No items yet.
                </td>
              </tr>
            ) : (
              v.lines.map((line, i) => (
                <tr key={line.id}>
                  <td className={s.colNo}>{i + 1}</td>
                  <td className={s.colDesc}>
                    <span className={s.itemTitle}>{line.title}</span>
                    {line.rest ? <span className={s.itemRest}>{line.rest}</span> : null}
                  </td>
                  {anyPeriod ? <td className={s.colPeriod}>{line.period}</td> : null}
                  <td className={s.colAmount}>{v.fmt(line.amount)}</td>
                </tr>
              ))
            )}
          </tbody>
        </table>

        <section className={s.mid}>
          <div className={s.payBy}>
            {payment ? (
              <>
                <p className={s.payTitle}>Pay By:</p>
                {payment.method.trim() ? (
                  <p>
                    {payment.method}
                    {payment.reference.trim() ? `: ${payment.reference}` : ""}
                  </p>
                ) : null}
                {Number(payment.amount) ? <p>Amount: {money(payment.amount, v.currency)}</p> : null}
                {payment.date ? <p>Date: {formatDate(payment.date)}</p> : null}
              </>
            ) : null}
          </div>

          <div className={s.sums}>
            <p>
              <span>Sub Total:</span>
              <span>{v.fmt(v.sums.subtotal)}</span>
            </p>
            {v.hasTax ? (
              <p>
                <span>
                  {v.taxLabel} ({v.taxRate}%)
                </span>
                <span>{v.fmt(v.sums.tax)}</span>
              </p>
            ) : null}
            <p>
              <span>Discount{v.discountPct ? ` (${v.discountPct}%)` : ""}</span>
              <span>{v.hasDiscount ? `− ${v.fmt(v.sums.discount)}` : v.fmt(0)}</span>
            </p>
            {v.hasPaid ? (
              <p>
                <span>Paid:</span>
                <span>− {v.fmt(v.sums.paid)}</span>
              </p>
            ) : null}
            <p className={s.grand}>
              <span>{v.hasPaid ? "Balance Due:" : "Grand Total:"}</span>
              <span>{v.fmt(v.hasPaid ? v.sums.balance : v.sums.total)}</span>
            </p>
          </div>
        </section>

        {(invoice.notes.trim() || invoice.terms.trim()) && (
          <section className={s.mustRead}>
            <p className={s.mustTitle}>Must Read:</p>
            {invoice.notes.trim() ? <p>{invoice.notes}</p> : null}
            {invoice.terms.trim() ? <p>{invoice.terms}</p> : null}
          </section>
        )}
      </div>

      <footer className={s.foot}>
        <BottomCurve className={s.bottomCurve} />
        <div className={s.footInner}>
          {invoice.from.phone.trim() ? (
            <p>
              <PhoneIcon />
              {invoice.from.phone}
            </p>
          ) : null}
          {invoice.from.email.trim() ? (
            <p>
              <MailIcon />
              {invoice.from.email}
            </p>
          ) : null}
          {invoice.from.address.trim() ? (
            <p>
              <PinIcon />
              {invoice.from.address.replace(/\n/g, ", ")}
            </p>
          ) : null}
        </div>
      </footer>
    </div>
  )
}

export default Arc
