import * as React from "react"
import Header from "../components/Header"
import Seo from "../components/Seo"
import InvoiceForm from "../components/invoice/InvoiceForm"
import InvoiceDoc from "../components/invoice/InvoiceDoc"
import StylePicker from "../components/invoice/StylePicker"
import { emptyInvoice, loadInvoice, saveInvoice } from "../lib/invoice"
import * as s from "../components/invoice/Invoice.module.css"

/**
 * THE INVOICE BUILDER — MTC-FCS-003, 004 and 005.
 * ============================================================================
 * Fill the form on the left, watch the document build on the right, pick a
 * colour and (if you care) a layout, print it to PDF.
 *
 * ── TWO COPIES OF THE DOCUMENT, ON PURPOSE ─────────────────────────────────
 * The preview is scaled with a transform to fit the column, and printing a
 * transformed element scales the paper with it. So a second, unscaled copy is
 * rendered off-screen carrying #invoice-print, and that is the one the print
 * stylesheet reveals. Both render from the same component and the same state,
 * so they cannot disagree.
 *
 * ── NOTHING LEAVES THE BROWSER ─────────────────────────────────────────────
 * An invoice carries a customer's name, address and what they were charged.
 * None of it is posted anywhere — the draft lives in localStorage and the PDF
 * is produced by the browser's own print pipeline. There is no upload step to
 * audit because there is no upload.
 */

const A4_WIDTH = 794

const InvoiceBuilderPage = () => {
  const [invoice, setInvoice] = React.useState(emptyInvoice)
  const [hydrated, setHydrated] = React.useState(false)
  const [scale, setScale] = React.useState(1)
  const [height, setHeight] = React.useState(0)
  const paper = React.useRef(null)
  const doc = React.useRef(null)

  React.useEffect(() => {
    const saved = loadInvoice()
    if (saved) setInvoice(saved)
    setHydrated(true)
  }, [])

  React.useEffect(() => {
    if (hydrated) saveInvoice(invoice)
  }, [invoice, hydrated])

  // The paper is a fixed 794px wide; the column it sits in is not.
  React.useEffect(() => {
    const outer = paper.current
    const inner = doc.current
    if (!outer || !inner) return undefined

    const measure = () => {
      const next = Math.min(1, outer.clientWidth / A4_WIDTH)
      setScale(next)
      setHeight(inner.scrollHeight * next)
    }

    measure()
    const ro = new ResizeObserver(measure)
    ro.observe(outer)
    ro.observe(inner)
    return () => ro.disconnect()
  }, [invoice, hydrated])

  const update = patch => setInvoice(current => ({ ...current, ...patch }))

  const reset = () => {
    if (window.confirm("Clear this invoice and start a new one?")) setInvoice(emptyInvoice())
  }

  return (
    <>
      <Header />
      <main className={s.page} data-print="hide">
        <div className={`container ${s.wide}`}>
          <div className={s.head}>
            <h1 className={s.title}>Invoice builder</h1>
            <p className={s.lead}>
              Build an invoice, pick a colour, and save it as a PDF. Everything stays in your
              browser — nothing is uploaded.
            </p>
          </div>

          <StylePicker invoice={invoice} update={update} />

          <div className={s.layout}>
            <InvoiceForm invoice={invoice} update={update} />

            <div className={s.previewCol}>
              <div className={s.previewBar}>
                <span className={s.previewLabel}>Live preview · A4</span>
                <button type="button" className={s.link} onClick={reset}>
                  Start a new invoice
                </button>
                <button type="button" className="btn btn--sm" onClick={() => window.print()}>
                  Download PDF
                </button>
              </div>

              <div
                className={s.paper}
                ref={paper}
                style={{ height: height ? `${height}px` : undefined }}
              >
                <div
                  ref={doc}
                  className={s.paperScale}
                  style={{ transform: `scale(${scale})`, width: `${A4_WIDTH}px` }}
                >
                  <InvoiceDoc invoice={invoice} />
                </div>
              </div>
            </div>
          </div>
        </div>
      </main>

      {/* The unscaled copy the print stylesheet reveals. */}
      <div className="print-only" aria-hidden="true">
        <InvoiceDoc invoice={invoice} forPrint />
      </div>
    </>
  )
}

export const Head = () => (
  <Seo
    title="Free invoice builder"
    description="Build a professional invoice in your browser, pick a colour, and save it as a PDF. Free for contractors."
  />
)

export default InvoiceBuilderPage
