import * as React from "react"
import { CURRENCIES, emptyDetail, emptyLine, emptyPayment, lineTotal, money } from "../../lib/invoice"
import { readImageFile } from "../../lib/read-image"
import PhoneInput from "../PhoneInput"
import * as s from "./Invoice.module.css"

/**
 * Everything on the left-hand side: the fields that fill the document.
 *
 * ── ADD AND REMOVE IS THE WHOLE FEATURE ────────────────────────────────────
 * The brief asked for items that add and remove simply, so a row is one click
 * to add and one to remove, the remove control sits on the row it removes, and
 * the LAST row cannot be deleted — an invoice with no line items is not a
 * state worth being able to reach by accident.
 *
 * ── NUMBERS ARE HELD AS TYPED ──────────────────────────────────────────────
 * Quantity and rate stay strings in the input and are coerced by lib/invoice
 * when it does arithmetic. Parsing on every keystroke fights the person typing
 * "1." on the way to "1.5", and a field that erases the decimal point as you
 * reach for it is maddening on a form somebody fills in twenty times a week.
 */

const Field = ({ label, note, children }) => (
  <div className={s.field}>
    <label>{label}</label>
    {children}
    {note ? <p className={s.note}>{note}</p> : null}
  </div>
)

const InvoiceForm = ({ invoice, update }) => {
  const [logoError, setLogoError] = React.useState("")
  const logoInput = React.useRef(null)

  const setFrom = (key, value) => update({ from: { ...invoice.from, [key]: value } })
  const setTo = (key, value) => update({ to: { ...invoice.to, [key]: value } })

  const setLine = (id, key, value) =>
    update({ lines: invoice.lines.map(l => (l.id === id ? { ...l, [key]: value } : l)) })

  const addLine = () => update({ lines: [...invoice.lines, emptyLine()] })

  /* Job details and payments are optional extras. They are edited the same
     way as line items — add a row, fill it, remove it — so there is one
     interaction to learn rather than three. */
  const setRow = (key, id, field, value) =>
    update({ [key]: invoice[key].map(r => (r.id === id ? { ...r, [field]: value } : r)) })

  const addRow = (key, make) => update({ [key]: [...(invoice[key] || []), make()] })

  const removeRow = (key, id) => update({ [key]: invoice[key].filter(r => r.id !== id) })

  const removeLine = id => {
    if (invoice.lines.length <= 1) return
    update({ lines: invoice.lines.filter(l => l.id !== id) })
  }

  const pickLogo = async file => {
    setLogoError("")
    try {
      // A logo on a 794px page never needs more than a few hundred pixels.
      setFrom("logo", await readImageFile(file, { maxEdge: 400 }))
    } catch (err) {
      setLogoError(err.message)
    }
  }

  return (
    <div className={s.form}>
      <section className={s.card}>
        <h2 className={s.cardTitle}>Your details</h2>

        <div className={s.logoRow}>
          {invoice.from.logo ? (
            <img src={invoice.from.logo} alt="" className={s.logoThumb} />
          ) : (
            <span className={s.logoThumb} />
          )}
          <div>
            <button type="button" className={s.link} onClick={() => logoInput.current.click()}>
              {invoice.from.logo ? "Replace logo" : "Add a logo"}
            </button>
            {invoice.from.logo ? (
              <>
                {" · "}
                <button type="button" className={s.link} onClick={() => setFrom("logo", "")}>
                  Remove
                </button>
              </>
            ) : null}
          </div>
          <input
            ref={logoInput}
            type="file"
            accept="image/*"
            hidden
            onChange={e => {
              const file = e.target.files && e.target.files[0]
              if (file) pickLogo(file)
              e.target.value = ""
            }}
          />
        </div>
        {logoError ? <p className={s.error}>{logoError}</p> : null}

        <Field label="Business name">
          <input value={invoice.from.name} onChange={e => setFrom("name", e.target.value)} />
        </Field>
        <div className={s.row2}>
          <Field label="Email">
            <input
              type="email"
              value={invoice.from.email}
              onChange={e => setFrom("email", e.target.value)}
            />
          </Field>
          <Field label="Phone">
            <PhoneInput
              value={invoice.from.phone}
              onChange={next => setFrom("phone", next)}
              placeholder="(555) 123-4567"
              maxLength={24}
            />
          </Field>
        </div>
        <Field label="Address">
          <textarea
            rows={3}
            value={invoice.from.address}
            onChange={e => setFrom("address", e.target.value)}
          />
        </Field>
      </section>

      <section className={s.card}>
        <h2 className={s.cardTitle}>Bill to</h2>
        <Field label="Customer name">
          <input value={invoice.to.name} onChange={e => setTo("name", e.target.value)} />
        </Field>
        <Field label="Email">
          <input type="email" value={invoice.to.email} onChange={e => setTo("email", e.target.value)} />
        </Field>
        <Field label="Address">
          <textarea rows={3} value={invoice.to.address} onChange={e => setTo("address", e.target.value)} />
        </Field>
      </section>

      <section className={s.card}>
        <h2 className={s.cardTitle}>Invoice details</h2>
        <div className={s.row2}>
          <Field label="Invoice number">
            <input value={invoice.number} onChange={e => update({ number: e.target.value })} />
          </Field>
          <Field label="Currency">
            <select value={invoice.currency} onChange={e => update({ currency: e.target.value })}>
              {CURRENCIES.map(c => (
                <option key={c.code} value={c.code}>
                  {c.code} — {c.label}
                </option>
              ))}
            </select>
          </Field>
        </div>
        <div className={s.row2}>
          <Field label="Issue date">
            <input type="date" value={invoice.issuedOn} onChange={e => update({ issuedOn: e.target.value })} />
          </Field>
          <Field label="Due date">
            <input type="date" value={invoice.dueOn} onChange={e => update({ dueOn: e.target.value })} />
          </Field>
        </div>
      </section>

      <section className={s.card}>
        <div className={s.cardHead}>
          <h2 className={s.cardTitle}>Items</h2>
          <button type="button" className={s.addBtn} onClick={addLine}>
            + Add item
          </button>
        </div>

        <div className={s.lines}>
          {invoice.lines.map((line, i) => (
            <div key={line.id} className={s.line}>
              <div className={s.lineHead}>
                <span className={s.lineNum}>{i + 1}</span>
                <span className={s.lineAmount}>{money(lineTotal(line), invoice.currency)}</span>
                <button
                  type="button"
                  className={s.removeBtn}
                  onClick={() => removeLine(line.id)}
                  disabled={invoice.lines.length <= 1}
                  aria-label={`Remove item ${i + 1}`}
                  title={invoice.lines.length <= 1 ? "An invoice needs at least one item" : "Remove"}
                >
                  ×
                </button>
              </div>
              <textarea
                rows={2}
                className={s.lineDesc}
                placeholder="What are you billing for?"
                value={line.description}
                onChange={e => setLine(line.id, "description", e.target.value)}
              />
              <input
                className={s.linePeriod}
                placeholder="Period or dates (optional)"
                value={line.period || ""}
                onChange={e => setLine(line.id, "period", e.target.value)}
                maxLength={32}
              />
              <div className={s.lineNums}>
                <label>
                  <span>Qty</span>
                  <input
                    inputMode="decimal"
                    value={line.quantity}
                    onChange={e => setLine(line.id, "quantity", e.target.value)}
                  />
                </label>
                <label>
                  <span>Rate</span>
                  <input
                    inputMode="decimal"
                    value={line.rate}
                    onChange={e => setLine(line.id, "rate", e.target.value)}
                  />
                </label>
              </div>
            </div>
          ))}
        </div>
      </section>

      <section className={s.card}>
        <h2 className={s.cardTitle}>Tax, discount and payment</h2>
        <div className={s.row2}>
          <Field label="Tax label">
            <input value={invoice.taxLabel} onChange={e => update({ taxLabel: e.target.value })} />
          </Field>
          <Field label="Tax rate (%)">
            <input
              inputMode="decimal"
              value={invoice.taxRate}
              onChange={e => update({ taxRate: e.target.value })}
            />
          </Field>
        </div>
        <div className={s.row2}>
          <Field label="Discount">
            <select
              value={invoice.discountMode}
              onChange={e => update({ discountMode: e.target.value })}
            >
              <option value="none">No discount</option>
              <option value="percent">Percentage</option>
              <option value="fixed">Fixed amount</option>
            </select>
          </Field>
          {invoice.discountMode !== "none" ? (
            <Field label={invoice.discountMode === "percent" ? "Discount (%)" : "Discount amount"}>
              <input
                inputMode="decimal"
                value={invoice.discountValue}
                onChange={e => update({ discountValue: e.target.value })}
              />
            </Field>
          ) : (
            <span />
          )}
        </div>
        <Field label="Amount already paid" note="Leave at zero to bill the full total.">
          <input
            inputMode="decimal"
            value={invoice.amountPaid}
            onChange={e => update({ amountPaid: e.target.value })}
          />
        </Field>
      </section>

      <section className={s.card}>
        <div className={s.cardHead}>
          <h2 className={s.cardTitle}>Job details</h2>
          <button
            type="button"
            className={s.addBtn}
            onClick={() => addRow("details", emptyDetail)}
            disabled={(invoice.details || []).length >= 6}
          >
            + Add
          </button>
        </div>

        {(invoice.details || []).length === 0 ? (
          <p className={s.note}>
            Optional. Job number, start date, permit, site — whatever this job needs recording.
            Shown by designs that have a grid for it.
          </p>
        ) : (
          <div className={s.lines}>
            {invoice.details.map(d => (
              <div key={d.id} className={s.pairRow}>
                <input
                  className={s.pairLabel}
                  value={d.label}
                  placeholder="Label"
                  onChange={e => setRow("details", d.id, "label", e.target.value)}
                  maxLength={24}
                />
                <input
                  className={s.pairValue}
                  value={d.value}
                  placeholder="Value"
                  onChange={e => setRow("details", d.id, "value", e.target.value)}
                  maxLength={32}
                />
                <button
                  type="button"
                  className={s.removeBtn}
                  onClick={() => removeRow("details", d.id)}
                  aria-label="Remove detail"
                >
                  ×
                </button>
              </div>
            ))}
          </div>
        )}
      </section>

      <section className={s.card}>
        <div className={s.cardHead}>
          <h2 className={s.cardTitle}>Payments received</h2>
          <button
            type="button"
            className={s.addBtn}
            onClick={() => addRow("payments", emptyPayment)}
          >
            + Add
          </button>
        </div>

        {(invoice.payments || []).length === 0 ? (
          <p className={s.note}>
            Optional. Record part-payments so the invoice shows what was paid and when, instead of
            one unexplained line in the totals.
          </p>
        ) : (
          <div className={s.lines}>
            {invoice.payments.map((p, i) => (
              <div key={p.id} className={s.line}>
                <div className={s.lineHead}>
                  <span className={s.lineNum}>{i + 1}</span>
                  <span className={s.lineAmount}>{money(p.amount, invoice.currency)}</span>
                  <button
                    type="button"
                    className={s.removeBtn}
                    onClick={() => removeRow("payments", p.id)}
                    aria-label={`Remove payment ${i + 1}`}
                  >
                    ×
                  </button>
                </div>
                <div className={s.row2}>
                  <input
                    className={s.lineDesc}
                    value={p.method}
                    placeholder="Method (e.g. Bank transfer)"
                    onChange={e => setRow("payments", p.id, "method", e.target.value)}
                    maxLength={40}
                  />
                  <input
                    className={s.lineDesc}
                    type="date"
                    value={p.date}
                    onChange={e => setRow("payments", p.id, "date", e.target.value)}
                  />
                </div>
                <div className={s.row2} style={{ marginTop: 10 }}>
                  <input
                    className={s.lineDesc}
                    value={p.reference}
                    placeholder="Reference"
                    onChange={e => setRow("payments", p.id, "reference", e.target.value)}
                    maxLength={40}
                  />
                  <input
                    className={s.lineDesc}
                    inputMode="decimal"
                    value={p.amount}
                    placeholder="Amount"
                    onChange={e => setRow("payments", p.id, "amount", e.target.value)}
                  />
                </div>
              </div>
            ))}
          </div>
        )}
      </section>

      <section className={s.card}>
        <h2 className={s.cardTitle}>Signature</h2>
        <p className={s.note} style={{ marginBottom: 14 }}>
          Optional. Shown by designs that have a place for it, set in a script face — we do not
          take an uploaded signature image.
        </p>
        <div className={s.row2}>
          <Field label="Name">
            <input
              value={invoice.signature.name}
              onChange={e => update({ signature: { ...invoice.signature, name: e.target.value } })}
              maxLength={40}
            />
          </Field>
          <Field label="Title">
            <input
              value={invoice.signature.title}
              onChange={e => update({ signature: { ...invoice.signature, title: e.target.value } })}
              placeholder="e.g. Owner"
              maxLength={40}
            />
          </Field>
        </div>
      </section>

      <section className={s.card}>
        <h2 className={s.cardTitle}>Notes and terms</h2>
        <Field label="Notes">
          <textarea rows={3} value={invoice.notes} onChange={e => update({ notes: e.target.value })} />
        </Field>
        <Field label="Terms">
          <textarea rows={2} value={invoice.terms} onChange={e => update({ terms: e.target.value })} />
        </Field>
      </section>
    </div>
  )
}

export default InvoiceForm
