import * as React from "react"
import { layoutById } from "../../data/invoice-layouts"
import { paletteById } from "../../data/invoice-palettes"
import Agency from "./templates/Agency"
import Detailed from "./templates/Detailed"
import Panel from "./templates/Panel"
import Signature from "./templates/Signature"
import Arc from "./templates/Arc"
import Bright from "./templates/Bright"
import Clinic from "./templates/Clinic"
import Cinema from "./templates/Cinema"
import { formatPhone } from "../../lib/phone"

/**
 * THE INVOICE DOCUMENT — the dispatcher.
 * ============================================================================
 * Two independent choices meet here: a LAYOUT (the shape of the page) and a
 * PALETTE (its two colours). Every layout reads the same palette, so the two
 * lists multiply instead of being eight fixed combinations — which is what
 * they were at first, and why there was no way to have a red invoice in the
 * standard layout.
 *
 * The layouts share their arithmetic: `prepare()` in templates/shared.js hands
 * each one the same computed totals, so a design can never disagree with its
 * own numbers.
 *
 * ── IT IS RENDERED AT TRUE A4 ──────────────────────────────────────────────
 * 794 x 1123 px is A4 at 96dpi. The preview scales it with a transform and the
 * printed copy is this same element unscaled, so what is on screen is the PDF.
 */

const REGISTRY = {
  agency: Agency,
  detailed: Detailed,
  panel: Panel,
  signature: Signature,
  arc: Arc,
  bright: Bright,
  sidebar: Clinic,
  ticket: Cinema,
}

const InvoiceDoc = ({ invoice, forPrint = false }) => {
  const layout = layoutById(invoice.layoutId)
  const palette = paletteById(invoice.paletteId)
  const Layout = REGISTRY[layout.id] || Agency

  // The house phone format is applied once, here, rather than in eight
  // designs — this is the seam every design is handed its invoice through, so
  // no layout can print a number in a shape of its own. MTC-FCS-011.
  const doc = React.useMemo(
    () => ({ ...invoice, from: { ...invoice.from, phone: formatPhone(invoice.from.phone) } }),
    [invoice]
  )

  return (
    <article
      id={forPrint ? "invoice-print" : undefined}
      data-invoice-layout={layout.id}
      data-invoice-palette={palette.id}
    >
      <Layout invoice={doc} t={palette} />
    </article>
  )
}

export default InvoiceDoc
