import * as React from "react"
import { INVOICE_PALETTES } from "../../data/invoice-palettes"
import { INVOICE_LAYOUTS } from "../../data/invoice-layouts"
import * as s from "./Invoice.module.css"

/**
 * Two tabs, because they are two different decisions.
 *
 * COLOUR is the one almost everybody makes — eight palettes over the same
 * page, the way the website builder offers themes. DESIGN changes the shape of
 * the document and most people will never touch it, so it sits behind its own
 * tab rather than competing for the same row of cards.
 *
 * They are independent on purpose: any colour works with any layout, which is
 * the whole reason the two lists were split apart.
 */
const StylePicker = ({ invoice, update }) => {
  const [tab, setTab] = React.useState("colour")

  return (
    <section className={s.styles}>
      <div className={s.tabs} role="tablist" aria-label="Invoice style">
        {[
          { id: "colour", label: "Colour" },
          { id: "design", label: "Design" },
        ].map(item => (
          <button
            key={item.id}
            type="button"
            role="tab"
            aria-selected={tab === item.id}
            className={`${s.tab} ${tab === item.id ? s.tabOn : ""}`}
            onClick={() => setTab(item.id)}
          >
            {item.label}
            <span className={s.tabCount}>
              {item.id === "colour" ? INVOICE_PALETTES.length : INVOICE_LAYOUTS.length}
            </span>
          </button>
        ))}
      </div>

      {tab === "colour" ? (
        <div className={s.swatchGrid} role="radiogroup" aria-label="Invoice colour">
          {INVOICE_PALETTES.map(p => (
            <button
              key={p.id}
              type="button"
              role="radio"
              aria-checked={invoice.paletteId === p.id}
              className={`${s.swatchCard} ${invoice.paletteId === p.id ? s.swatchOn : ""}`}
              onClick={() => update({ paletteId: p.id })}
            >
              <span className={s.swatchRow}>
                <span className={s.swatch} style={{ background: p.ink }} />
                <span className={s.swatch} style={{ background: p.primary }} />
                <span className={s.swatch} style={{ background: p.accent }} />
              </span>
              <strong>{p.label}</strong>
              <span>{p.blurb}</span>
            </button>
          ))}
        </div>
      ) : (
        <div className={s.layoutGrid} role="radiogroup" aria-label="Invoice design">
          {INVOICE_LAYOUTS.map(l => (
            <button
              key={l.id}
              type="button"
              role="radio"
              aria-checked={invoice.layoutId === l.id}
              className={`${s.layoutCard} ${invoice.layoutId === l.id ? s.layoutOn : ""}`}
              onClick={() => update({ layoutId: l.id })}
            >
              <LayoutSketch id={l.id} />
              <strong>{l.label}</strong>
              <span>{l.blurb}</span>
            </button>
          ))}
        </div>
      )}
    </section>
  )
}

