import * as React from "react"
import { prepare, MailIcon, PhoneIcon, PinIcon } from "./shared"
import * as s from "./Panel.module.css"

/**
 * PANEL — an accent block at the corner, contacts in the header, numbered rows.
 *
 * Four things make this a third design rather than a recolour of the other two:
 *
 *  1. The word INVOICE lives in a solid accent block punched into the top-right
 *     corner, overlapping the dark header rather than sitting beside it.
 *  2. The issuer's phone, email and address sit INSIDE the header band with
 *     icons, so the page below opens straight onto the client.
 *  3. A four-across stats strip — label above value — instead of the two-row
 *     grid Detailed uses. Same optional data, read completely differently.
 *  4. The items table head is filled with the ACCENT and its rows are
 *     numbered, where Standard fills it with near-black and Detailed leaves it
 *     unfilled.
 *
 * ── TERMS BECOME BULLETS WHEN THEY ARE A LIST ──────────────────────────────
 * Multi-line terms render as a bulleted list, because that is what a numbered
 * set of conditions is. A single line stays a sentence — bulleting one item
 * looks like a mistake.
 */

/** Splits free text into list items, or returns null if it is one line. */
function asBullets(text) {
  const items = String(text || "")
    .split("\n")
    .map(line => line.replace(/^\s*[-•*]\s*/, "").trim())
    .filter(Boolean)
  return items.length > 1 ? items : null
}

const Panel = ({ invoice, t }) => {
  const v = prepare(invoice)

  const details = (invoice.details || []).filter(d => d.label.trim() || d.value.trim())
  const termsBullets = asBullets(invoice.terms)
  const notesBullets = asBullets(invoice.notes)

  return (
    <div
      className={s.page}
      style={{ "--c": t.primary, "--on-c": t.onPrimary, "--a": t.accent, "--ink": t.ink, "--surface": t.surface }}
    >
      <header className={s.band}>
        <div className={s.bandInner}>
          <div className={s.brand}>
            {invoice.from.logo ? (
              <img src={invoice.from.logo} alt="" className={s.logo} />
            ) : (
              <span className={s.brandName}>{invoice.from.name || ""}</span>
            )}
          </div>

          <div className={s.contacts}>
            {(invoice.from.phone.trim() || invoice.from.email.trim()) && (
              <p>
                {invoice.from.phone.trim() ? (
                  <span>
                    <PhoneIcon />
                    {invoice.from.phone}
                  </span>
                ) : null}
                {invoice.from.email.trim() ? (
                  <span>
                    <MailIcon />
                    {invoice.from.email}
                  </span>
                ) : null}
              </p>
            )}
            {invoice.from.address.trim() ? (
              <p>
                <span>
                  <PinIcon />
                  {invoice.from.address.replace(/\n/g, ", ")}
                </span>
              </p>
            ) : null}
          </div>
        </div>

        <div className={s.corner}>
          <span>Invoice</span>
        </div>
      </header>

      <div className={s.body}>
        <section className={s.parties}>
          <div>
            <p className={s.partyLabel}>Client Info:</p>
            {invoice.to.name.trim() ? <p className={s.partyName}>{invoice.to.name}</p> : null}
            {invoice.to.address.trim() ? <p className={s.partyLine}>{invoice.to.address}</p> : null}
            {invoice.to.email.trim() ? <p className={s.partyLine}>{invoice.to.email}</p> : null}
          </div>

          <dl className={s.meta}>
            {invoice.number.trim() ? (
              <>
                <dt>Invoice No:</dt>
                <dd>{invoice.number}</dd>
              </>
            ) : null}
            {v.issued ? (
              <>
                <dt>Invoice Date:</dt>
                <dd>{v.issued}</dd>
              </>
            ) : null}
            {v.due ? (
              <>
                <dt>Due Date:</dt>
                <dd>{v.due}</dd>
              </>
            ) : null}
          </dl>
        </section>

        {details.length > 0 && (
          <section className={s.stats}>
            {details.slice(0, 4).map(d => (
              <div key={d.id}>
                <span className={s.statLabel}>{d.label}</span>
                <span className={s.statValue}>{d.value}</span>
              </div>
            ))}
          </section>
        )}

        <table className={s.table}>
          <thead>
            <tr>
              <th className={s.colNo}>S No.</th>
              <th className={s.colDesc}>Description</th>
              <th className={s.colPrice}>Price</th>
              <th className={s.colAmount}>Amount</th>
            </tr>
          </thead>
          <tbody>
            {v.lines.length === 0 ? (
              <tr>
                <td colSpan={4} className={s.empty}>
                  No items yet.
                </td>
              </tr>
            ) : (
              v.lines.map((line, i) => (
                <tr key={line.id}>
                  <td className={s.colNo}>{i + 1}</td>
                  <td className={s.colDesc}>
                    <span className={s.itemTitle}>{line.title}</span>
                    {line.rest ? <span className={s.itemRest}>{line.rest}</span> : null}
                  </td>
                  <td className={s.colPrice}>
                    {Number(line.quantity) === 1
                      ? v.fmt(line.rate)
                      : `${Number(line.quantity) || 0} × ${v.fmt(line.rate)}`}
                  </td>
                  <td className={s.colAmount}>{v.fmt(line.amount)}</td>
                </tr>
              ))
            )}
          </tbody>
        </table>

        <section className={s.foot}>
          <div className={s.rules}>
            {invoice.notes.trim() ? (
              <>
                <p className={s.rulesTitle}>Additional Information:</p>
                {notesBullets ? (
                  <ul>
                    {notesBullets.map(item => (
                      <li key={item}>{item}</li>
                    ))}
                  </ul>
                ) : (
                  <p className={s.rulesText}>{invoice.notes}</p>
                )}
              </>
            ) : null}

            {invoice.terms.trim() ? (
              <>
                <p className={s.rulesTitle}>Terms:</p>
                {termsBullets ? (
                  <ul>
                    {termsBullets.map(item => (
                      <li key={item}>{item}</li>
                    ))}
                  </ul>
                ) : (
                  <p className={s.rulesText}>{invoice.terms}</p>
                )}
              </>
            ) : null}
          </div>

          <div className={s.sums}>
            <p>
              <span>Sub Total:</span>
              <span>{v.fmt(v.sums.subtotal)}</span>
            </p>
            {v.hasDiscount ? (
              <p>
                <span>Discount{v.discountPct ? ` (${v.discountPct}%)` : ""}</span>
                <span>−{v.fmt(v.sums.discount)}</span>
              </p>
            ) : null}
            {v.hasTax ? (
              <p>
                <span>
                  {v.taxLabel} ({v.taxRate}%)
                </span>
                <span>{v.fmt(v.sums.tax)}</span>
              </p>
            ) : null}
            {v.hasPaid ? (
              <p>
                <span>Paid:</span>
                <span>−{v.fmt(v.sums.paid)}</span>
              </p>
            ) : null}
            <p className={s.grand}>
              <span>{v.hasPaid ? "Balance Due:" : "Grand Total:"}</span>
              <span>{v.fmt(v.hasPaid ? v.sums.balance : v.sums.total)}</span>
            </p>
          </div>
        </section>
      </div>

      <footer className={s.bandFoot} aria-hidden="true" />
    </div>
  )
}

export default Panel
