import * as React from "react"
import { prepare, MailIcon, PhoneIcon } from "./shared"
import * as s from "./Agency.module.css"

/**
 * AGENCY — the reference layout.
 *
 * Solid dark bands top and bottom, a coloured logo block overhanging the
 * header's lower-left, a dark table head, and the grand total called out in a
 * filled bar. The bands do the work here: they frame the page so the middle
 * can stay almost entirely white, which is what makes the numbers read.
 *
 * The overhanging block is the one piece of real structure — it ties the
 * header to the body instead of leaving a band sitting on top of a document.
 */
const Agency = ({ invoice, t }) => {
  const v = prepare(invoice)

  return (
    <div className={s.page} style={{ "--c": t.primary, "--on-c": t.onPrimary, "--ink": t.ink }}>
      <header className={s.band}>
        <div className={s.logoBlock}>
          {invoice.from.logo ? (
            <img src={invoice.from.logo} alt="" className={s.logo} />
          ) : (
            <span className={s.logoText}>{invoice.from.name || ""}</span>
          )}
        </div>
        <p className={s.word}>Invoice</p>
      </header>

      <div className={s.body}>
        <dl className={s.meta}>
          {invoice.number.trim() ? (
            <>
              <dt>Invoice No:</dt>
              <dd>{invoice.number}</dd>
            </>
          ) : null}
          {v.issued ? (
            <>
              <dt>Invoice Date:</dt>
              <dd>{v.issued}</dd>
            </>
          ) : null}
          {v.due ? (
            <>
              <dt>Due Date:</dt>
              <dd>{v.due}</dd>
            </>
          ) : null}
        </dl>

        <section className={s.parties}>
          <div>
            <p className={s.partyLabel}>Invoice To:</p>
            {invoice.to.name.trim() ? <p className={s.partyName}>{invoice.to.name}</p> : null}
            {invoice.to.address.trim() ? <p className={s.partyLines}>{invoice.to.address}</p> : null}
            {invoice.to.email.trim() ? <p className={s.partyLines}>{invoice.to.email}</p> : null}
          </div>
          <div className={s.payTo}>
            <p className={s.partyLabel}>Pay To:</p>
            {invoice.from.name.trim() ? <p className={s.partyName}>{invoice.from.name}</p> : null}
            {invoice.from.address.trim() ? (
              <p className={s.partyLines}>{invoice.from.address}</p>
            ) : null}
            {invoice.from.email.trim() ? <p className={s.partyLines}>{invoice.from.email}</p> : null}
          </div>
        </section>

        <table className={s.table}>
          <thead>
            <tr>
              <th className={s.colService}>Service</th>
              <th className={s.colDesc}>Description</th>
              <th className={s.num}>Qty</th>
              <th className={s.num}>Price</th>
              <th className={s.num}>Total</th>
            </tr>
          </thead>
          <tbody>
            {v.lines.length === 0 ? (
              <tr>
                <td colSpan={5} className={s.empty}>
                  No items yet.
                </td>
              </tr>
            ) : (
              v.lines.map(line => (
                <tr key={line.id}>
                  <td className={s.colService}>{line.title}</td>
                  <td className={s.colDesc}>{line.rest}</td>
                  <td className={s.num}>{Number(line.quantity) || 0}</td>
                  <td className={s.num}>{v.fmt(line.rate)}</td>
                  <td className={s.num}>{v.fmt(line.amount)}</td>
                </tr>
              ))
            )}
          </tbody>
        </table>

        <section className={s.foot}>
          <div className={s.notes}>
            {invoice.notes.trim() ? (
              <>
                <p className={s.notesTitle}>Additional Information:</p>
                <p className={s.notesText}>{invoice.notes}</p>
              </>
            ) : null}
            {invoice.terms.trim() ? (
              <>
                <p className={s.notesTitle}>Terms:</p>
                <p className={s.notesText}>{invoice.terms}</p>
              </>
            ) : null}
          </div>

          <div className={s.sums}>
            <p>
              <span>Sub Total:</span>
              <span>{v.fmt(v.sums.subtotal)}</span>
            </p>
            {v.hasDiscount ? (
              <p>
                <span>Discount{v.discountPct ? ` (${v.discountPct}%)` : ""}:</span>
                <span>−{v.fmt(v.sums.discount)}</span>
              </p>
            ) : null}
            {v.hasTax ? (
              <p>
                <span>
                  {v.taxLabel} ({v.taxRate}%):
                </span>
                <span>{v.fmt(v.sums.tax)}</span>
              </p>
            ) : null}
            {v.hasPaid ? (
              <p>
                <span>Paid:</span>
                <span>−{v.fmt(v.sums.paid)}</span>
              </p>
            ) : null}
            <p className={s.grand}>
              <span>Grand Total:</span>
              <span>{v.fmt(v.hasPaid ? v.sums.balance : v.sums.total)}</span>
            </p>
          </div>
        </section>
      </div>

      <footer className={s.bandFoot}>
        {invoice.from.phone.trim() ? (
          <span>
            <PhoneIcon />
            {invoice.from.phone}
          </span>
        ) : (
          <span />
        )}
        {invoice.from.email.trim() ? (
          <span>
            <MailIcon />
            {invoice.from.email}
          </span>
        ) : null}
      </footer>
    </div>
  )
}

export default Agency
