import * as React from "react"
import { prepare } from "./shared"
import * as s from "./Cinema.module.css"

/**
 * CINEMA — a ticket, perforated stub and all.
 *
 * The stub is the structure: a dashed tear line down the page with punched
 * notches top and bottom, and the three things somebody actually needs at a
 * glance — reference, date, amount — printed on it. Everything else stays on
 * the main body, exactly as a real ticket is laid out.
 *
 * Alternating dark rows and tabular figures carry the rest of the register.
 */
const Cinema = ({ invoice, t }) => {
  const v = prepare(invoice)

  return (
    <div className={s.page} style={{ "--c": t.primary, "--on-c": t.onPrimary, "--ink": t.ink }}>
      <div className={s.ticket}>
        <div className={s.main}>
          <header className={s.head}>
            <div>
              {invoice.from.logo ? (
                <img src={invoice.from.logo} alt="" className={s.logo} />
              ) : null}
              {invoice.from.name.trim() ? <p className={s.house}>{invoice.from.name}</p> : null}
            </div>
            <p className={s.word}>Invoice</p>
          </header>

          <section className={s.parties}>
            <div>
              <p className={s.label}>Billed to</p>
              {invoice.to.name.trim() ? <p className={s.name}>{invoice.to.name}</p> : null}
              {invoice.to.address.trim() ? <p className={s.lines}>{invoice.to.address}</p> : null}
              {invoice.to.email.trim() ? <p className={s.lines}>{invoice.to.email}</p> : null}
            </div>
            <div>
              <p className={s.label}>From</p>
              {invoice.from.address.trim() ? (
                <p className={s.lines}>{invoice.from.address}</p>
              ) : null}
              {invoice.from.phone.trim() ? <p className={s.lines}>{invoice.from.phone}</p> : null}
              {invoice.from.email.trim() ? <p className={s.lines}>{invoice.from.email}</p> : null}
            </div>
          </section>

          <table className={s.table}>
            <thead>
              <tr>
                <th>Item</th>
                <th className={s.num}>Qty</th>
                <th className={s.num}>Price</th>
                <th className={s.num}>Total</th>
              </tr>
            </thead>
            <tbody>
              {v.lines.length === 0 ? (
                <tr>
                  <td colSpan={4} className={s.empty}>
                    No items yet.
                  </td>
                </tr>
              ) : (
                v.lines.map(line => (
                  <tr key={line.id}>
                    <td>
                      <span className={s.itemTitle}>{line.title}</span>
                      {line.rest ? <span className={s.itemRest}>{line.rest}</span> : null}
                    </td>
                    <td className={s.num}>{Number(line.quantity) || 0}</td>
                    <td className={s.num}>{v.fmt(line.rate)}</td>
                    <td className={s.num}>{v.fmt(line.amount)}</td>
                  </tr>
                ))
              )}
            </tbody>
          </table>

          <section className={s.sums}>
            <p>
              <span>Subtotal</span>
              <span>{v.fmt(v.sums.subtotal)}</span>
            </p>
            {v.hasDiscount ? (
              <p>
                <span>Discount{v.discountPct ? ` (${v.discountPct}%)` : ""}</span>
                <span>−{v.fmt(v.sums.discount)}</span>
              </p>
            ) : null}
            {v.hasTax ? (
              <p>
                <span>
                  {v.taxLabel} ({v.taxRate}%)
                </span>
                <span>{v.fmt(v.sums.tax)}</span>
              </p>
            ) : null}
            {v.hasPaid ? (
              <p>
                <span>Paid</span>
                <span>−{v.fmt(v.sums.paid)}</span>
              </p>
            ) : null}
          </section>

          {(invoice.notes.trim() || invoice.terms.trim()) && (
            <section className={s.notes}>
              {invoice.notes.trim() ? <p>{invoice.notes}</p> : null}
              {invoice.terms.trim() ? <p className={s.terms}>{invoice.terms}</p> : null}
            </section>
          )}
        </div>

        <aside className={s.stub}>
          <span className={s.notchTop} aria-hidden="true" />
          <span className={s.notchBottom} aria-hidden="true" />

          <p className={s.stubWord}>Invoice</p>

          <div className={s.stubBlock}>
            <span>Ref</span>
            {invoice.number.trim() || "—"}
          </div>
          <div className={s.stubBlock}>
            <span>Issued</span>
            {v.issued || "—"}
          </div>
          {v.due ? (
            <div className={s.stubBlock}>
              <span>Due</span>
              {v.due}
            </div>
          ) : null}

          <div className={s.stubTotal}>
            <span>{v.hasPaid ? "Balance" : "Total"}</span>
            <strong>{v.fmt(v.hasPaid ? v.sums.balance : v.sums.total)}</strong>
          </div>
        </aside>
      </div>
    </div>
  )
}

export default Cinema
