import * as React from "react"
import { prepare, MailIcon, PhoneIcon, PinIcon } from "./shared"
import * as s from "./Clinic.module.css"

/**
 * CLINIC — a full-height coloured sidebar carrying the practice's details.
 *
 * The structural idea is the column, not the band: everything about the issuer
 * lives down the left edge, which leaves the whole right-hand page for the
 * patient, the items and the total. That is how medical statements are
 * usually set, and it means the main area never has to compete with a
 * letterhead.
 *
 * Rounded corners and a tinted table head keep it calm. Nothing shouts.
 */
const Clinic = ({ invoice, t }) => {
  const v = prepare(invoice)

  return (
    <div className={s.page} style={{ "--c": t.primary, "--on-c": t.onPrimary, "--ink": t.ink, "--surface": t.surface }}>
      <aside className={s.rail}>
        <div className={s.railTop}>
          {invoice.from.logo ? (
            <img src={invoice.from.logo} alt="" className={s.logo} />
          ) : (
            <span className={s.mark} aria-hidden="true">
              <svg viewBox="0 0 24 24" fill="currentColor">
                <rect x="10" y="3" width="4" height="18" rx="1.2" />
                <rect x="3" y="10" width="18" height="4" rx="1.2" />
              </svg>
            </span>
          )}
          {invoice.from.name.trim() ? <p className={s.railName}>{invoice.from.name}</p> : null}
        </div>

        <div className={s.railInfo}>
          {invoice.from.address.trim() ? (
            <p>
              <PinIcon />
              <span>{invoice.from.address}</span>
            </p>
          ) : null}
          {invoice.from.phone.trim() ? (
            <p>
              <PhoneIcon />
              <span>{invoice.from.phone}</span>
            </p>
          ) : null}
          {invoice.from.email.trim() ? (
            <p>
              <MailIcon />
              <span>{invoice.from.email}</span>
            </p>
          ) : null}
        </div>

        {invoice.terms.trim() ? (
          <div className={s.railTerms}>
            <p className={s.railTermsTitle}>Terms</p>
            <p>{invoice.terms}</p>
          </div>
        ) : null}
      </aside>

      <main className={s.main}>
        <header className={s.head}>
          <p className={s.word}>Invoice</p>
          <dl className={s.meta}>
            {invoice.number.trim() ? (
              <>
                <dt>No.</dt>
                <dd>{invoice.number}</dd>
              </>
            ) : null}
            {v.issued ? (
              <>
                <dt>Issued</dt>
                <dd>{v.issued}</dd>
              </>
            ) : null}
            {v.due ? (
              <>
                <dt>Due</dt>
                <dd>{v.due}</dd>
              </>
            ) : null}
          </dl>
        </header>

        <section className={s.billTo}>
          <p className={s.label}>Billed to</p>
          {invoice.to.name.trim() ? <p className={s.name}>{invoice.to.name}</p> : null}
          {invoice.to.address.trim() ? <p className={s.lines}>{invoice.to.address}</p> : null}
          {invoice.to.email.trim() ? <p className={s.lines}>{invoice.to.email}</p> : null}
        </section>

        <table className={s.table}>
          <thead>
            <tr>
              <th>Service</th>
              <th className={s.num}>Qty</th>
              <th className={s.num}>Rate</th>
              <th className={s.num}>Amount</th>
            </tr>
          </thead>
          <tbody>
            {v.lines.length === 0 ? (
              <tr>
                <td colSpan={4} className={s.empty}>
                  No items yet.
                </td>
              </tr>
            ) : (
              v.lines.map(line => (
                <tr key={line.id}>
                  <td>
                    <span className={s.itemTitle}>{line.title}</span>
                    {line.rest ? <span className={s.itemRest}>{line.rest}</span> : null}
                  </td>
                  <td className={s.num}>{Number(line.quantity) || 0}</td>
                  <td className={s.num}>{v.fmt(line.rate)}</td>
                  <td className={s.num}>{v.fmt(line.amount)}</td>
                </tr>
              ))
            )}
          </tbody>
        </table>

        <section className={s.sums}>
          <p>
            <span>Subtotal</span>
            <span>{v.fmt(v.sums.subtotal)}</span>
          </p>
          {v.hasDiscount ? (
            <p>
              <span>Discount{v.discountPct ? ` (${v.discountPct}%)` : ""}</span>
              <span>−{v.fmt(v.sums.discount)}</span>
            </p>
          ) : null}
          {v.hasTax ? (
            <p>
              <span>
                {v.taxLabel} ({v.taxRate}%)
              </span>
              <span>{v.fmt(v.sums.tax)}</span>
            </p>
          ) : null}
          {v.hasPaid ? (
            <p>
              <span>Paid</span>
              <span>−{v.fmt(v.sums.paid)}</span>
            </p>
          ) : null}
        </section>

        <section className={s.due}>
          <span>{v.hasPaid ? "Balance due" : "Total due"}</span>
          <strong>{v.fmt(v.hasPaid ? v.sums.balance : v.sums.total)}</strong>
        </section>

        {invoice.notes.trim() ? (
          <section className={s.notes}>
            <p className={s.label}>Notes</p>
            <p>{invoice.notes}</p>
          </section>
        ) : null}
      </main>
    </div>
  )
}

export default Clinic
